package cryptoutil

import "testing"

// Ciphertext generated by real CryptoJS.AES.encrypt("mySecretPassw0rd", "test-secret-123")
// in Node — pins compatibility with data already stored by the Node backend.
func TestDecryptNodeCryptoJSOutput(t *testing.T) {
	secret := "test-secret-123"
	nodeCiphertext := "U2FsdGVkX19jcOhy4ioheCQQ849xiTyX+iYLDB9kwuD87sae5W9yYYczOexM9SzS"

	got, err := Decrypt(nodeCiphertext, secret)
	if err != nil {
		t.Fatalf("Decrypt error: %v", err)
	}
	if got != "mySecretPassw0rd" {
		t.Fatalf("got %q, want %q", got, "mySecretPassw0rd")
	}
}

func TestRoundTrip(t *testing.T) {
	secret := "another-secret"
	plain := "4219"

	enc, err := Encrypt(plain, secret)
	if err != nil {
		t.Fatalf("Encrypt error: %v", err)
	}
	dec, err := Decrypt(enc, secret)
	if err != nil {
		t.Fatalf("Decrypt error: %v", err)
	}
	if dec != plain {
		t.Fatalf("got %q, want %q", dec, plain)
	}
}
